#include <bits/stdc++.h>
using namespace std;
int main(){vector<pair<int,int>> pairs;for(int i=0;i<6;i++)for(int j=i+1;j<6;j++)pairs.push_back({i,j});int n=15; vector<pair<int,int>> edges; for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(pairs[i].first!=pairs[j].first && pairs[i].first!=pairs[j].second && pairs[i].second!=pairs[j].first && pairs[i].second!=pairs[j].second)edges.push_back({i,j});cerr<<"N "<<n<<" M "<<edges.size()<<"\n"; array<int,16> best;array<long long,16> ways{};best.fill(1000);int c[15];long long total=0;vector<array<long long,16>> hist(46);function<void(int,int,int)> rec=[&](int i,int occ,int mono){if(i==15){total++;hist[mono][occ]++;if(mono<best[occ])best[occ]=mono,ways[occ]=1;else if(mono==best[occ])ways[occ]++;return;}for(int color=0;color<3;color++){c[i]=color;int extra=0;for(auto[a,b]:edges)if(b==i&&c[a]==color)extra++;rec(i+1,occ+(color==0),mono+extra);}};rec(0,0,0);cout<<"total "<<total<<"\n";for(int i=0;i<=15;i++)cout<<i<<" "<<best[i]<<" "<<ways[i]<<"\n";cout<<"zero_field " ;int glob=*min_element(best.begin(),best.end());long long deg=0;for(int i=0;i<16;i++)if(best[i]==glob)deg+=ways[i];cout<<glob<<" "<<deg<<"\n";cout<<"hist\n";for(int en=0;en<=45;en++){long long s=0;for(int i=0;i<16;i++)s+=hist[en][i];if(s)cout<<en<<" "<<s<<"\n";}}
